public class METCustomerMDFPosting_SalesInvoice extends METCustomerMDFPosting
{
    MetShipmentId shipmentId;

}

Method.Source:
public MetShipmentId parmShipmentId(MetShipmentId _shipmentId = shipmentId)
{
    shipmentId = _shipmentId;

    return shipmentId;
}

Query updateQuery(Query _query)
{
    Query ret = super(_query);

    QueryBuildDataSource qbds = ret.dataSourceTable(tableNum(METCustomerMDFConsolidationTable));
    qbds.addRange(fieldNum(METCustomerMDFConsolidationTable, ShipmentId)).value(queryValue(shipmentId));

    return ret;
}

void createSalesInvoiceLines(METCustomerMDFConsolidationTable _consolidationPosting)
{
    METCustomerMDFConsolidationTable consolidationTable;

    while select forupdate consolidationTable
        where consolidationTable.CustAccount == _consolidationPosting.CustAccount
        && consolidationTable.ConsolidationMethod == METConsolidationMethodEDT::Shipment
        && consolidationTable.ApplicationMethod == METApplicationMethodEDT::FreeTextInvoice
        && consolidationTable.ShipmentId == _consolidationPosting.ShipmentId
    {
        // Logic to create free text invoice lines for daily consolidation
        this.processConsolidationTable(consolidationTable);
    }
}

RecId createSalesInvoiceLine(METCustomerMDFConsolidationTable _consolidationTable)
{
    RecId recId;
    // Logic to create free text invoice line and return its RecId
    return recId;
}
